const plain = document.getElementById('link-external');
const navHome = document.getElementById('nav-home');
const btnLink = document.getElementById('link-btn');
if (!plain || !navHome || !btnLink) return false;

// Accessible name matches visible label
if (!plain.textContent.includes('read more')) return false;

if (!document.body.classList.contains('ai4a11y-highlight-links')) return true;

function getLuminance(rgbStr) {
  const m = rgbStr.match(/\d+/g);
  if (!m) return null;
  const [r, g, b] = m.slice(0, 3).map(v => {
    const c = Number(v) / 255;
    return c <= 0.03928 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  });
  return 0.2126 * r + 0.7152 * g + 0.0722 * b;
}
function contrast(c1, c2) {
  const l1 = getLuminance(c1);
  const l2 = getLuminance(c2);
  if (l1 === null || l2 === null) return null;
  return (Math.max(l1, l2) + 0.05) / (Math.min(l1, l2) + 0.05);
}

// Check plain link focus outline and contrast on white background
plain.focus();
const plainStyle = window.getComputedStyle(plain);
const plainOutlineWidth = parseFloat(plainStyle.outlineWidth);
const plainOutlineColor = plainStyle.outlineColor;
const plainRatio = contrast(plainOutlineColor, 'rgb(255, 255, 255)');
plain.blur();
if (plainOutlineWidth < 2 || plainRatio === null || plainRatio < 3.0) return false;

// Check navHome focus outline contrast on dark header background (#1a202c = rgb(26, 32, 44))
navHome.focus();
const navStyle = window.getComputedStyle(navHome);
const navOutlineWidth = parseFloat(navStyle.outlineWidth);
const navOutlineColor = navStyle.outlineColor;
const navRatio = contrast(navOutlineColor, 'rgb(26, 32, 44)');
navHome.blur();
if (navOutlineWidth < 2 || navRatio === null || navRatio < 3.0) return false;

// Check btnLink focus outline contrast on button background (#0b57d0 = rgb(11, 87, 208))
btnLink.focus();
const btnStyle = window.getComputedStyle(btnLink);
const btnOutlineWidth = parseFloat(btnStyle.outlineWidth);
const btnOutlineColor = btnStyle.outlineColor;
const btnRatio = contrast(btnOutlineColor, 'rgb(11, 87, 208)');
const btnRect = btnLink.getBoundingClientRect();
// Target size for block/button link >= 24x24
const btnSizeOk = btnRect.width >= 24 && btnRect.height >= 24;
// Ensure element not obscured when focused
const hit = document.elementFromPoint(btnRect.left + btnRect.width / 2, btnRect.top + btnRect.height / 2);
const notObscured = (hit === btnLink || btnLink.contains(hit));
btnLink.blur();

if (btnOutlineWidth < 2 || btnRatio === null || btnRatio < 3.0 || !btnSizeOk || !notObscured) return false;

return true;

const described = document.getElementById('link-described');
const top = document.getElementById('link-top');
const wsFragment = document.getElementById('link-ws-fragment');
const mail = document.getElementById('link-email');
const phone = document.getElementById('link-phone');
const anchor = document.getElementById('back-anchor');
const btn = document.getElementById('newsletter-btn');
if (!described || !top || !wsFragment || !mail || !phone || !anchor || !btn) return false;

// Described title must stay exactly as the author wrote it
if (described.getAttribute('title') !== 'W3C Web Accessibility Initiative Guidelines') return false;
if (described.hasAttribute('data-ai4a11y-linkhl')) return false;

// Non-web destinations and fragments must not receive host title
if (top.hasAttribute('title') || top.hasAttribute('data-ai4a11y-linkhl')) return false;
