if (mail.hasAttribute('title') || mail.hasAttribute('data-ai4a11y-linkhl')) return false;
if (phone.hasAttribute('title') || phone.hasAttribute('data-ai4a11y-linkhl')) return false;
if (anchor.hasAttribute('title') || btn.hasAttribute('title')) return false;

return true;
